// Access storage lazily: the browser can throw even when reading localStorage.
// Preferences must never prevent a screen or a completed server action from working.
export function createSafeStorage(resolveStorage) {
  return {
    getItem(key) {
      try { return resolveStorage()?.getItem(key) ?? null; } catch { return null; }
    },
    setItem(key, value) {
      try { resolveStorage()?.setItem(key, value); } catch { /* Storage is optional. */ }
    },
    removeItem(key) {
      try { resolveStorage()?.removeItem(key); } catch { /* Storage is optional. */ }
    },
  };
}

export const browserStorage = createSafeStorage(() => globalThis.localStorage);

export function readStoredStringSet(key, storage = browserStorage) {
  try {
    const value = JSON.parse(storage.getItem(key) ?? '[]');
    return new Set(Array.isArray(value) ? value.filter(item => typeof item === 'string') : []);
  } catch { return new Set(); }
}

export function writeStoredStringSet(key, values, limit, storage = browserStorage) {
  const items = [...values].filter(item => typeof item === 'string');
  const bounded = Number.isInteger(limit) && limit > 0 ? items.slice(-limit) : items;
  storage.setItem(key, JSON.stringify(bounded));
}
